```go
package main

import "fmt"

func sum(values ...int) int {
    total := 0
    for _, value := range values { total += value }
    return total
}

func main() {
    fmt.Println(sum())
    fmt.Println(sum(2, 3, 5))
}
```
The output is `0` and `10`. Both calls reach the same slice-based loop inside `sum`.

```go
package main

import "fmt"

func double(values ...int) {
    for index := range values { values[index] *= 2 }
}

func main() {
    numbers := []int{2, 3, 4}
    double(numbers...)
    fmt.Println(numbers)
}
```
The output is `[4 6 8]`. `numbers...` passes the slice unchanged, so the callee's element assignments reach the same backing array.

```go
package main

import "fmt"

func inline(values ...int) int { return len(values) }
func collected(values []int) int { return len(values) }

func main() {
    values := []int{2, 4, 6}
    fmt.Println(inline(2, 4, 6))
    fmt.Println(inline(values...))
    fmt.Println(collected(values))
}
```
All calls print `3`, but the first API accepts individual values while the second declares one collection as its input.

```go
package main

import "fmt"

func printNames(names ...string) { fmt.Println(names) }

func main() {
    names := []string{"ana", "lee"}
    all := append([]string{"owner"}, names...)
    printNames(all...)
}
```
The output is `[owner ana lee]`. The call uses one expanded slice instead of trying to mix `"owner"` and `names...` in the variadic positions.
